<?php $title='Reports';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Reports & Analytics</h1><p>Operational visibility across clients, projects, services, billing and activity.</p></div></div><section class="grid two"><div class="panel"><h2>Clients by type</h2><table><tr><th>Type</th><th>Count</th></tr><?php foreach($clients_by_type as $r):?><tr><td><?=e($r['client_type'])?></td><td><?=e($r['total'])?></td></tr><?php endforeach;?></table></div><div class="panel"><h2>Invoice status</h2><table><tr><th>Status</th><th>Count</th><th>Amount</th><th>Balance</th></tr><?php foreach($invoice_status as $r):?><tr><td><?=e($r['status'])?></td><td><?=e($r['total'])?></td><td><?=money((float)$r['amount'])?></td><td><?=money((float)$r['balance'])?></td></tr><?php endforeach;?></table></div><div class="panel"><h2>Top services</h2><?php foreach($top_services as $r):?><div class="metric-row"><span><?=e($r['name'])?></span><strong><?=$r['total']?></strong></div><?php endforeach;?></div><div class="panel"><h2>Most active modules</h2><?php foreach($activities as $r):?><div class="metric-row"><span><?=e($r['module_name'])?></span><strong><?=$r['total']?></strong></div><?php endforeach;?></div></section><?php require __DIR__.'/../layouts/footer.php';?>
